//! Rengar. Ferocity is a shared 0-4 counter generated by casting any basic
//! ability (or landing Savagery's stab); a cast made at 4 stacks consumes
//! them, uses the Ferocity-empowered damage, and grants a free extra cast.
//! Savagery arms the next attack with a bonus stab and attack speed instead
//! of dealing damage on cast and has no cast time; Battle Roar has no cast
//! time and deals damage on cast; Bola Strike has a 0.25s cast time and
//! keeps Rengar busy for it; Thrill of the Hunt opens the fight, arming the
//! first attack with a 100% AD bonus hit. Casts go one at a time via
//! `busy_until`.

use crate::fight::{shave, Driver, Engine, Events, Kind, St};
use crate::fx::*;
use crate::kit::Kit;
use crate::num::*;
use crate::sheet::Sheet;

/// Battle Roar, and Bola Strike's cast then its Ferocity-empowered extra
/// cast, go out as events.
const EV_W: u8 = 0;
const EV_E: u8 = 1;
const EV_E_EXTRA: u8 = 2;

#[derive(Clone, Debug, PartialEq)]
pub struct GenDriver {
    ranks: Ranks,
    attack_range: f64,
    p_max: i64,
    q_dmg: f64,
    q_emp_dmg: f64,
    q_cd: f64,
    q_as_pct: f64,
    q_as_dur: f64,
    q_emp_as_pct: f64,
    q_emp_as_dur: f64,
    w_dmg: f64,
    w_emp_dmg: f64,
    w_cd: f64,
    e_dmg: f64,
    e_emp_dmg: f64,
    e_cd: f64,
    e_cast_s: f64,
    r_ad_ratio: f64,
    src_q: SourceId,
    src_w: SourceId,
    src_e: SourceId,
    src_r: SourceId,
    s: State,
    s0: State,
}

/// Everything a fight moves.
#[derive(Clone, Copy, Debug, PartialEq)]
struct State {
    /// The cast in progress ends here: no other cast, no attack before it.
    busy_until: f64,
    ferocity: i64,
    /// Pending Savagery stabs, in order; 0.0 means the slot is empty.
    q_stab_a: f64,
    q_stab_b: f64,
    /// Savagery's 40% bonus AS for the next two attacks: charges left, and
    /// the window's expiry.
    q_as_count: i64,
    q_as_until: f64,
    /// The Ferocity-empowered 5s bonus AS buff's expiry.
    q_emp_as_until: f64,
    w_ready: f64,
    e_ready: f64,
    /// The Ferocity-empowered free extra cast of Bola Strike, pending at
    /// this time (INF: none pending).
    e_extra_at: f64,
    /// Thrill of the Hunt's bonus damage, pending on the next attack.
    r_pending: bool,
}

impl GenDriver {
    /// The earliest a cast readied at `ready` can start: not before now, and
    /// not inside another cast.
    fn castable_at(&self, e: &Engine, ready: f64) -> f64 {
        pymax(pymax(ready, e.st.t), self.s.busy_until)
    }

    /// A cast with a cast time just started: no other cast and no attack
    /// until it ends (an attack already due later keeps its time).
    fn busy_for(&mut self, e: &mut Engine, cast_s: f64) {
        self.s.busy_until = e.st.t + cast_s;
        e.st.next_attack = pymax(e.st.next_attack, self.s.busy_until);
    }

    /// A basic ability cast generates a Ferocity stack, or consumes all 4 if
    /// already maxed (returning true: this cast is Ferocity-empowered).
    fn ferocity_on_cast(&mut self) -> bool {
        if self.s.ferocity >= self.p_max {
            self.s.ferocity = 0;
            true
        } else {
            self.s.ferocity = imin(self.s.ferocity + 1, self.p_max);
            false
        }
    }

    /// Landing Savagery's stab also generates a Ferocity stack.
    fn ferocity_add(&mut self) {
        self.s.ferocity = imin(self.s.ferocity + 1, self.p_max);
    }

    fn arm_stab(&mut self, dmg: f64) {
        if self.s.q_stab_a <= 0.0 {
            self.s.q_stab_a = dmg;
        } else {
            self.s.q_stab_b = dmg;
        }
    }

    fn grant_q_as(&mut self, t: f64) {
        self.s.q_as_count = imin(self.s.q_as_count + 2, 4);
        self.s.q_as_until = pymax(self.s.q_as_until, t + self.q_as_dur);
    }
}

impl Driver for GenDriver {
    fn new(kit: &Kit, sheet: &Sheet, level: i64, ranks: Ranks, _prestacked: bool)
        -> Result<Self, String> {
        let state = State {
            busy_until: 0.0,
            ferocity: 0,
            q_stab_a: 0.0,
            q_stab_b: 0.0,
            q_as_count: 0,
            q_as_until: 0.0,
            q_emp_as_until: 0.0,
            w_ready: 0.0,
            e_ready: 0.0,
            e_extra_at: INF,
            r_pending: false,
        };
        Ok(GenDriver {
            ranks,
            attack_range: sheet.base_attack_range,
            p_max: kit.num("gen.P.maxFerocity")? as i64,
            q_dmg: kit.hit("gen.Q.damage", ranks.q, sheet)?,
            q_emp_dmg: kit.at_level("gen.Q.empDamage.baseByLevel", level)?
                + kit.num("gen.Q.empDamage.adRatio")? * sheet.ad,
            q_cd: kit.at_rank("abilities.Q.cooldownS", ranks.q)?,
            q_as_pct: kit.num("gen.Q.asBonusPct")?,
            q_as_dur: kit.num("gen.Q.asBonusDurationS")?,
            q_emp_as_pct: kit.at_level("gen.Q.empAsPctByLevel", level)?,
            q_emp_as_dur: kit.num("gen.Q.empAsDurationS")?,
            w_dmg: kit.hit("gen.W.damage", ranks.w, sheet)?,
            w_emp_dmg: kit.at_level("gen.W.empDamage.baseByLevel", level)?
                + kit.num("gen.W.empDamage.apRatio")? * sheet.ap,
            w_cd: kit.at_rank("abilities.W.cooldownS", ranks.w)?,
            e_dmg: kit.hit("gen.E.damage", ranks.e, sheet)?,
            e_emp_dmg: kit.at_level("gen.E.empDamage.baseByLevel", level)?
                + kit.num("gen.E.empDamage.bonusAdRatio")? * sheet.ad_bonus,
            e_cd: kit.at_rank("abilities.E.cooldownS", ranks.e)?,
            e_cast_s: kit.num("gen.E.castTimeS")?,
            r_ad_ratio: kit.num("gen.R.bonusDamage.adRatio")?,
            src_q: SRC_Q,
            src_w: SRC_W,
            src_e: SRC_E,
            src_r: SRC_R,
            s: state,
            s0: state,
        })
    }

    fn reset(&mut self) {
        self.s = self.s0;
    }

    fn ranged(&self) -> bool {
        self.attack_range > MELEE_MAX_RANGE
    }

    fn attack_range(&self) -> f64 {
        self.attack_range
    }

    fn bonus_as(&self, t: f64) -> f64 {
        let mut b = 0.0;
        if self.s.q_as_count > 0 && t < self.s.q_as_until {
            b += self.q_as_pct;
        }
        if t < self.s.q_emp_as_until {
            b += self.q_emp_as_pct;
        }
        b
    }

    fn shave_cooldowns(&mut self, st: &mut St, t: f64, factor: f64) {
        shave(&mut st.q_ready, t, factor);
        shave(&mut self.s.w_ready, t, factor);
        shave(&mut self.s.e_ready, t, factor);
    }

    fn before_attack(&mut self, e: &mut Engine) {
        if self.s.q_as_count > 0 && e.st.t < self.s.q_as_until {
            self.s.q_as_count -= 1;
        }
    }

    fn after_attack(&mut self, e: &mut Engine) {
        if self.s.q_stab_a > 0.0 {
            e.deal(self.s.q_stab_a, DType::Physical, self.src_q, true, false, 1.0);
            self.ferocity_add();
            self.s.q_stab_a = self.s.q_stab_b;
            self.s.q_stab_b = 0.0;
        }
        if self.s.r_pending {
            self.s.r_pending = false;
            let dmg = e.p.ad * self.r_ad_ratio;
            e.deal(dmg, DType::Physical, self.src_r, false, false, 1.0);
        }
    }

    fn q_at(&self, e: &Engine) -> f64 {
        if self.ranks.q == 0 {
            return INF;
        }
        self.castable_at(e, e.st.q_ready)
    }

    fn cast_q(&mut self, e: &mut Engine) {
        // Savagery has no cast time: it does not call busy_for, but it was
        // still gated by castable_at via q_at above
        let t = e.st.t;
        let emp = self.ferocity_on_cast();
        let dmg = if emp { self.q_emp_dmg } else { self.q_dmg };
        self.arm_stab(dmg);
        self.grant_q_as(t);
        if emp {
            self.s.q_emp_as_until = t + self.q_emp_as_dur;
            // the extra free cast: Ferocity is now 0, so it is never itself
            // empowered; Savagery has no cast time so this resolves at the
            // same instant
            let emp2 = self.ferocity_on_cast();
            let dmg2 = if emp2 { self.q_emp_dmg } else { self.q_dmg };
            self.arm_stab(dmg2);
            self.grant_q_as(t);
        }
        e.prime_spellblade();
        e.st.q_ready = pymax(self.s.q_as_until, t) + e.basic_cd(self.q_cd);
        // Savagery resets Rengar's basic attack timer
        e.st.next_attack = pymin(e.st.next_attack, t);
    }

    fn cast_r(&mut self, e: &mut Engine) {
        if self.ranks.r == 0 {
            return;
        }
        self.ferocity_on_cast();
        self.s.r_pending = true;
        e.prime_spellblade();
    }

    fn events(&self, e: &Engine, out: &mut Events) -> usize {
        let mut n = 0;
        if self.ranks.w > 0 {
            out[n] = (self.castable_at(e, self.s.w_ready), Kind::Ev(EV_W));
            n += 1;
        }
        if self.ranks.e > 0 {
            if self.s.e_extra_at != INF {
                out[n] = (self.castable_at(e, self.s.e_extra_at), Kind::Ev(EV_E_EXTRA));
            } else {
                out[n] = (self.castable_at(e, self.s.e_ready), Kind::Ev(EV_E));
            }
            n += 1;
        }
        n
    }

    fn on_event(&mut self, e: &mut Engine, kind: Kind) {
        let t = e.st.t;
        match kind {
            Kind::Ev(EV_W) => {
                // Battle Roar has no cast time
                let emp = self.ferocity_on_cast();
                let dmg = if emp { self.w_emp_dmg } else { self.w_dmg };
                e.deal(dmg, DType::Magic, self.src_w, false, true, 1.0);
                e.ability_cast_proc();
                e.eclipse_hit();
                e.prime_spellblade();
                if emp {
                    let emp2 = self.ferocity_on_cast();
                    let dmg2 = if emp2 { self.w_emp_dmg } else { self.w_dmg };
                    e.deal(dmg2, DType::Magic, self.src_w, false, true, 1.0);
                    e.ability_cast_proc();
                    e.eclipse_hit();
                    e.prime_spellblade();
                }
                self.s.w_ready = t + e.basic_cd(self.w_cd);
            }
            Kind::Ev(EV_E) => {
                // Bola Strike's cast time keeps Rengar busy; if it consumes
                // max Ferocity, its free extra cast is a separate cast
                // instance and waits for this one's cast time to end
                let emp = self.ferocity_on_cast();
                let dmg = if emp { self.e_emp_dmg } else { self.e_dmg };
                e.deal(dmg, DType::Physical, self.src_e, false, true, 1.0);
                e.ability_cast_proc();
                e.eclipse_hit();
                e.prime_spellblade();
                self.s.e_ready = t + e.basic_cd(self.e_cd);
                self.busy_for(e, self.e_cast_s);
                self.s.e_extra_at = if emp { self.s.busy_until } else { INF };
            }
            Kind::Ev(EV_E_EXTRA) => {
                let emp2 = self.ferocity_on_cast();
                let dmg2 = if emp2 { self.e_emp_dmg } else { self.e_dmg };
                e.deal(dmg2, DType::Physical, self.src_e, false, true, 1.0);
                e.ability_cast_proc();
                e.eclipse_hit();
                e.prime_spellblade();
                self.s.e_extra_at = INF;
                self.busy_for(e, self.e_cast_s);
            }
            other => panic!("unhandled event {other:?}"),
        }
    }
}
